void HpaeSessionEffectNode::TraceSeOutput(HpaePcmBuffer *buf)
{
    if (buf == nullptr) {
        return;
    }
    size_t sampleCount = static_cast<size_t>(buf->GetFrameLen()) * buf->GetChannelCount();
    if (sampleCount == 0 || buf->GetPcmDataBuffer() == nullptr) {
        return;
    }
    PcmBlockStats stats = ComputePcmBlockStats(buf->GetPcmDataBuffer(), sampleCount);
    if (hasPrevOutSample_ && std::abs(stats.firstSample - prevOutLastSample_) > POP_JUMP_LOG_THRESHOLD) {
        AUDIO_WARNING_LOG("[SE::PopTrace] output jump sessionId=%{public}u status=%{public}s "
            "valid=%{public}d silence=%{public}d prevLast=%{public}f curFirst=%{public}f "
            "delta=%{public}f curPeak=%{public}f frameLen=%{public}u ch=%{public}u", ...);
    }
    prevOutLastSample_ = stats.lastSample;
    hasPrevOutSample_ = true;

void HpaeSinkInputNode::RewindHistoryBuffer(uint64_t rewindTime, uint64_t hdiFramePosition)
{
    CHECK_AND_RETURN_LOG(historyBuffer_, "historyBuffer_ is nullptr");
    hdiFramePosition_.store(hdiFramePosition);
    size_t requestFrames = ConvertUsToFrameCount(rewindTime, GetNodeInfo());
    size_t actualFrames = historyBuffer_->RewindBuffer(requestFrames);
    AUDIO_INFO_LOG("rewind request %{public}zu frames, actual %{public}zu, us=%{public}" PRIu64,
        requestFrames, actualFrames, rewindTime);
    rewindTime_.store(rewindTime);
    OnStreamInfoChange(false);
}

